#!/usr/bin/env python3
"""Helper to generate minimal .flf test fonts."""
import sys

def make_font(path, height=3, baseline=2, max_length=10, old_layout=0,
              comment_lines=1, comments=("test font",), hardblank="$",
              print_direction=None, full_layout=None, codetag_count=None,
              glyphs=None, endmark="@", signature=b"flf2a", raw_header=None,
              extra_after=None, line_ending="\n"):
    """glyphs: list of glyphs; each glyph is list of `height` row strings (no endmarks)."""
    hdr = raw_header
    if hdr is None:
        fields = [str(height), str(baseline), str(max_length), str(old_layout), str(comment_lines)]
        if print_direction is not None:
            fields.append(str(print_direction))
        if full_layout is not None:
            fields.append(str(full_layout))
        if codetag_count is not None:
            fields.append(str(codetag_count))
        hdr = signature + hardblank.encode() + b" " + " ".join(fields).encode()
    data = hdr + line_ending.encode()
    for c in comments:
        data += c.encode() + line_ending.encode()
    if glyphs:
        for g in glyphs:
            for i, row in enumerate(g):
                e = endmark * (2 if i == len(g) - 1 else 1)
                data += row.encode() + e.encode() + line_ending.encode()
    if extra_after:
        data += extra_after
    with open(path, "wb") as f:
        f.write(data if isinstance(data, bytes) else data.encode())

if __name__ == "__main__":
    # simple font: height 2, glyphs for 32-126, each glyph shows the char
    glyphs = []
    for code in range(32, 127):
        c = chr(code)
        glyphs.append([c + c, c])  # 2 rows
    make_font("/tmp/yourwork/full1.flf", height=2, baseline=1, glyphs=glyphs)
    print("wrote full1.flf")
